create extension if not exists pgcrypto;
create type public.member_role as enum ('admin','manager','technician','sales'); create type public.order_status as enum ('open','analysis','awaiting_approval','approved','in_maintenance','ready','delivered','cancelled'); create type public.transaction_type as enum ('income','expense');
create table public.companies(id uuid primary key default gen_random_uuid(),name text not null, business_type text, stripe_customer_id text unique, created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,created_at timestamptz not null default now());
create table public.company_members(company_id uuid references public.companies(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role public.member_role not null default 'admin',created_at timestamptz not null default now(),primary key(company_id,user_id));
create table public.customers(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,phone text,email text,document text, address text,city text,notes text,created_at timestamptz not null default now());
create table public.equipment(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,type text not null,brand text,model text,serial_number text,asset_tag text,notes text,created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,sku text,name text not null,category text not null,brand text,compatibility text,cost numeric(12,2) not null default 0 check(cost>=0),sale_price numeric(12,2) not null default 0 check(sale_price>=0),quantity integer not null default 0 check(quantity>=0),min_stock integer not null default 0 check(min_stock>=0),location text,description text,created_at timestamptz not null default now(),unique(company_id,sku));
create table public.service_orders(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,order_number bigint generated always as identity,customer_id uuid not null references public.customers(id),equipment_id uuid references public.equipment(id),reported_issue text not null,diagnosis text,service_performed text,technician_id uuid references auth.users(id),priority text not null default 'normal',status public.order_status not null default 'open',received_at timestamptz not null default now(),expected_date date,labor_value numeric(12,2) not null default 0,discount numeric(12,2) not null default 0,total numeric(12,2) not null default 0,notes text,created_at timestamptz not null default now());
create table public.service_order_items(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,service_order_id uuid not null references public.service_orders(id) on delete cascade,product_id uuid references public.products(id),description text,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null default 0);
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,product_id uuid not null references public.products(id),type text not null check(type in ('entry','exit','adjustment')),quantity integer not null,reason text,reference_type text,reference_id uuid,created_at timestamptz not null default now());
create table public.sales(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,sale_number bigint generated always as identity,customer_id uuid references public.customers(id),payment_method text not null,total numeric(12,2) not null check(total>=0),discount numeric(12,2) not null default 0,created_at timestamptz not null default now()); create table public.sale_items(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,sale_id uuid not null references public.sales(id) on delete cascade,product_id uuid not null references public.products(id),quantity integer not null check(quantity>0),unit_price numeric(12,2) not null);
create table public.financial_transactions(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,type public.transaction_type not null,description text not null,category text,amount numeric(12,2) not null check(amount>0),occurred_on date not null default current_date,payment_method text,status text not null default 'paid',created_at timestamptz not null default now());
create table public.subscriptions(company_id uuid primary key references public.companies(id) on delete cascade,stripe_customer_id text,stripe_subscription_id text unique,plan text not null default 'essencial',status text not null default 'trialing',current_period_end timestamptz,cancel_at_period_end boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create table public.stripe_events(id text primary key,type text not null,created_at timestamptz not null default now());
create index on public.customers(company_id);create index on public.equipment(company_id);create index on public.products(company_id);create index on public.service_orders(company_id,status);create index on public.sales(company_id,created_at);create index on public.financial_transactions(company_id,occurred_on);
create or replace function public.is_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.company_members where company_id=target and user_id=auth.uid())$$;
create or replace function public.bootstrap_company(company_name text,full_name text) returns uuid language plpgsql security definer set search_path=public as $$declare cid uuid;begin insert into public.profiles(id,full_name) values(auth.uid(),full_name) on conflict(id) do update set full_name=excluded.full_name;select company_id into cid from public.company_members where user_id=auth.uid() limit 1;if cid is null then insert into public.companies(name) values(company_name) returning id into cid;insert into public.company_members(company_id,user_id,role) values(cid,auth.uid(),'admin');insert into public.subscriptions(company_id,plan,status,current_period_end) values(cid,'essencial','trialing',now()+interval '7 days');end if;return cid;end$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$declare cid uuid;begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'name','')) on conflict(id) do nothing;insert into public.companies(name) values(coalesce(new.raw_user_meta_data->>'company_name','Minha empresa')) returning id into cid;insert into public.company_members(company_id,user_id,role) values(cid,new.id,'admin');insert into public.subscriptions(company_id,plan,status,current_period_end) values(cid,'essencial','trialing',now()+interval '7 days');return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.register_sale(p_company_id uuid,p_customer_id uuid,p_product_id uuid,p_quantity integer,p_payment_method text,p_discount numeric default 0) returns uuid language plpgsql security definer set search_path=public as $$declare p public.products; sid uuid; total_value numeric;begin if not public.is_member(p_company_id) then raise exception 'Not allowed';end if;select * into p from public.products where id=p_product_id and company_id=p_company_id for update;if not found then raise exception 'Produto não encontrado';end if;if p.quantity<p_quantity then raise exception 'Estoque insuficiente';end if;total_value=greatest(0,p.sale_price*p_quantity-p_discount);insert into public.sales(company_id,customer_id,payment_method,total,discount) values(p_company_id,p_customer_id,p_payment_method,total_value,p_discount) returning id into sid;insert into public.sale_items(company_id,sale_id,product_id,quantity,unit_price) values(p_company_id,sid,p_product_id,p_quantity,p.sale_price);update public.products set quantity=quantity-p_quantity where id=p_product_id;insert into public.inventory_movements(company_id,product_id,type,quantity,reason,reference_type,reference_id) values(p_company_id,p_product_id,'exit',-p_quantity,'Venda','sale',sid);insert into public.financial_transactions(company_id,type,description,category,amount,occurred_on,payment_method) values(p_company_id,'income','Venda #'||(select sale_number from public.sales where id=sid),'Venda',total_value,current_date,p_payment_method);return sid;end$$;
grant execute on function public.bootstrap_company(text,text),public.register_sale(uuid,uuid,uuid,integer,text,numeric) to authenticated;
alter table public.companies enable row level security;alter table public.profiles enable row level security;alter table public.company_members enable row level security;alter table public.customers enable row level security;alter table public.equipment enable row level security;alter table public.products enable row level security;alter table public.service_orders enable row level security;alter table public.service_order_items enable row level security;alter table public.inventory_movements enable row level security;alter table public.sales enable row level security;alter table public.sale_items enable row level security;alter table public.financial_transactions enable row level security;alter table public.subscriptions enable row level security;
create policy "members manage company" on public.companies for all using(public.is_member(id));create policy "users read profile" on public.profiles for select using(id=auth.uid());create policy "users manage own profile" on public.profiles for update using(id=auth.uid());create policy "members view membership" on public.company_members for select using(user_id=auth.uid() or public.is_member(company_id));
create policy "tenant customers" on public.customers for all using(public.is_member(company_id)) with check(public.is_member(company_id));create policy "tenant equipment" on public.equipment for all using(public.is_member(company_id)) with check(public.is_member(company_id));create policy "tenant products" on public.products for all using(public.is_member(company_id)) with check(public.is_member(company_id));create policy "tenant orders" on public.service_orders for all using(public.is_member(company_id)) with check(public.is_member(company_id));create policy "tenant order items" on public.service_order_items for all using(public.is_member(company_id)) with check(public.is_member(company_id));create policy "tenant movements" on public.inventory_movements for all using(public.is_member(company_id)) with check(public.is_member(company_id));create policy "tenant sales" on public.sales for all using(public.is_member(company_id)) with check(public.is_member(company_id));create policy "tenant sale items" on public.sale_items for all using(public.is_member(company_id)) with check(public.is_member(company_id));create policy "tenant transactions" on public.financial_transactions for all using(public.is_member(company_id)) with check(public.is_member(company_id));create policy "tenant subscription" on public.subscriptions for select using(public.is_member(company_id));
